-- lawyers_hub: large hotel management database (MySQL syntax)
-- Tables: guests, rooms, staff, bookings, outlet_orders
-- The data is messy on purpose. Profile it and clean it before analysing.
-- Run the WHOLE script (first lightning bolt in Workbench).

CREATE DATABASE IF NOT EXISTS lawyers_hub;
USE lawyers_hub;

DROP TABLE IF EXISTS guests;

CREATE TABLE guests (
    guest_id INT,
    first_name VARCHAR(60),
    last_name VARCHAR(60),
    email VARCHAR(100),
    phone VARCHAR(30),
    gender VARCHAR(10),
    date_of_birth VARCHAR(20),
    country VARCHAR(40),
    city VARCHAR(40),
    company_name VARCHAR(60),
    loyalty_tier VARCHAR(20),
    loyalty_points INT,
    total_stays INT,
    registered_on VARCHAR(20),
    preferred_language VARCHAR(20),
    vip_flag VARCHAR(10),
    newsletter_opt_in VARCHAR(10),
    special_requests VARCHAR(100),
    referral_source VARCHAR(30),
    last_updated DATETIME
);



DROP TABLE IF EXISTS rooms;

CREATE TABLE rooms (
    room_id INT,
    room_number INT,
    floor VARCHAR(20),
    room_type VARCHAR(30),
    bed_type VARCHAR(20),
    max_guests INT,
    size_sqm INT,
    view_type VARCHAR(20),
    nightly_rate DECIMAL(12,2),
    weekend_rate DECIMAL(12,2),
    smoking_allowed VARCHAR(10),
    has_balcony VARCHAR(10),
    has_kitchenette VARCHAR(10),
    accessible_room VARCHAR(10),
    status VARCHAR(20),
    last_renovated VARCHAR(20),
    housekeeping_zone VARCHAR(20),
    minibar_stocked VARCHAR(10),
    notes VARCHAR(100)
);


DROP TABLE IF EXISTS staff;

CREATE TABLE staff (
    staff_id INT,
    first_name VARCHAR(60),
    last_name VARCHAR(60),
    department VARCHAR(30),
    job_title VARCHAR(40),
    hire_date VARCHAR(20),
    employment_status VARCHAR(20),
    employment_type VARCHAR(20),
    monthly_salary DECIMAL(12,2),
    shift VARCHAR(20),
    supervisor_id INT,
    email VARCHAR(100),
    phone VARCHAR(30),
    work_location VARCHAR(40),
    training_completed VARCHAR(10),
    performance_rating INT,
    last_review_date VARCHAR(20),
    emergency_contact_phone VARCHAR(30),
    notes VARCHAR(100)
);


DROP TABLE IF EXISTS bookings;

CREATE TABLE bookings (
    booking_id INT,
    guest_id INT,
    room_id INT,
    booking_date VARCHAR(20),
    check_in VARCHAR(20),
    check_out VARCHAR(20),
    nights INT,
    adults INT,
    children INT,
    booking_channel VARCHAR(30),
    rate_applied DECIMAL(12,2),
    discount_pct DECIMAL(6,2),
    extras_amount DECIMAL(12,2),
    tax_amount DECIMAL(12,2),
    total_amount DECIMAL(12,2),
    deposit_paid DECIMAL(12,2),
    payment_method VARCHAR(30),
    payment_status VARCHAR(20),
    booking_status VARCHAR(20),
    cancellation_date VARCHAR(20),
    cancellation_reason VARCHAR(60),
    assigned_staff_id INT,
    special_requests VARCHAR(100),
    review_score INT
);






DROP TABLE IF EXISTS outlet_orders;

CREATE TABLE outlet_orders (
    order_id INT,
    booking_id INT,
    guest_id INT,
    outlet VARCHAR(30),
    order_date VARCHAR(20),
    order_time VARCHAR(20),
    item_name VARCHAR(60),
    item_category VARCHAR(30),
    quantity INT,
    unit_price DECIMAL(12,2),
    discount_amount DECIMAL(12,2),
    tax_amount DECIMAL(12,2),
    tip_amount DECIMAL(12,2),
    total_amount DECIMAL(12,2),
    payment_method VARCHAR(30),
    payment_status VARCHAR(20),
    server_id INT,
    table_number INT,
    order_status VARCHAR(20),
    kitchen_prep_minutes INT,
    customer_rating INT,
    room_charge_flag VARCHAR(5),
    notes VARCHAR(100)
);












SELECT (SELECT COUNT(*) FROM guests)        AS guest_rows,
       (SELECT COUNT(*) FROM rooms)         AS room_rows,
       (SELECT COUNT(*) FROM staff)         AS staff_rows,
       (SELECT COUNT(*) FROM bookings)      AS booking_rows,
       (SELECT COUNT(*) FROM outlet_orders) AS outlet_order_rows;
